const require_index = require("../useOrientation/index.js");
let react = require("react");
//#region src/useMobileLandscape/index.ts
function useMobileLandscape() {
	const [isMobileLandscape, setIsMobileLandscape] = (0, react.useState)(false);
	const [orientation] = require_index.useOrientation();
	(0, react.useEffect)(() => {
		const userAgent = window.navigator.userAgent;
		const isMobile = /Mobi|Android｜iphone/i.test(userAgent);
		setIsMobileLandscape(isMobile && orientation.type === "landscape-primary");
	}, [orientation.type]);
	return isMobileLandscape;
}
//#endregion
exports.useMobileLandscape = useMobileLandscape;
